using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Text.RegularExpressions;
namespace KlipperWinForms {using Obj=Dictionary<string,object>;
 static class Safety {
  sealed class Insn {public int Address,Size;public string Op,Args;}
  static int Reg(string s){s=s.Trim().TrimEnd('!');if(s=="sp")return 13;if(s=="lr")return 14;if(s=="pc")return 15;if(s=="ip")return 12;if(s=="fp")return 11;if(s=="sl")return 10;if(s=="sb")return 9;return Regex.IsMatch(s,@"^r\d+$")?int.Parse(s.Substring(1)):-1;}
  static long? Operand(string s,Dictionary<int,long> regs){s=s.Trim();if(s.StartsWith("#")){string n=s.Substring(1);return n.StartsWith("0x")?U.Number(n):long.Parse(n);}int r=Reg(s);return r>=0&&regs.ContainsKey(r)?regs[r]:(long?)null;}
  static List<Insn> Decode(byte[] data,int start,int size){string work=Path.Combine(Build.WorkRoot(),"klipper-cs-inspect-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(work);try{string file=Path.Combine(work,"code.bin");File.WriteAllBytes(file,data.Skip(start).Take(size).ToArray());string tc=Path.Combine(U.Assets,Json.S(U.Read(Path.Combine(U.Assets,"manifest.json")),"toolchain_directory"));var cc=new Compiler(tc,work,_=>{});string text=cc.Run("objdump",new[]{"-D","-b","binary","-m","arm","-M","force-thumb","--adjust-vma="+start,file});var list=new List<Insn>();foreach(var line in text.Split('\n')){var m=Regex.Match(line,@"^\s*([0-9a-f]+):\s+([0-9a-f]{4}(?:\s+[0-9a-f]{4})?)\s+([a-z][\w.]*)\s*(.*)$");if(m.Success)list.Add(new Insn{Address=Convert.ToInt32(m.Groups[1].Value,16),Size=Regex.Replace(m.Groups[2].Value,@"\s","").Length/2,Op=m.Groups[3].Value.Split('.')[0],Args=m.Groups[4].Value.Split('@',';')[0].Trim()});}return list;}finally{Directory.Delete(work,true);}}
  static bool Load(Insn i,byte[] data,Dictionary<int,long> regs){var p=i.Args.Split(',').Select(s=>s.Trim()).ToArray();if(p.Length<2)return false;int dest=Reg(p[0]);if(dest<0||dest==15)return false;long? v=null;
   if(i.Op=="ldr"&&i.Args.Contains("[pc")){var m=Regex.Match(i.Args,@"\[pc(?:,\s*#(-?(?:0x[0-9a-f]+|\d+)))?\]");if(!m.Success)return false;long offset=m.Groups[1].Success?U.Number(m.Groups[1].Value):0;int at=(int)(((i.Address+4)&~3)+offset);if(at>=0&&at+4<=data.Length)v=U.V32(data,at);}
   else if(new[]{"mov","movs","movw","movt"}.Contains(i.Op)){v=Operand(p[1],regs);if(p.Length>2){var shift=Regex.Match(p[2],@"^lsl\s+#(\d+)$");v=v.HasValue&&shift.Success?v.Value<<int.Parse(shift.Groups[1].Value):(long?)null;}if(i.Op=="movt")v=v.HasValue&&regs.ContainsKey(dest)?(regs[dest]&65535)|(v.Value<<16):(long?)null;}
   else if(new[]{"add","adds","sub","subs"}.Contains(i.Op)){long? left=p.Length==2?(regs.ContainsKey(dest)?regs[dest]:(long?)null):Operand(p[1],regs),right=Operand(p.Length==2?p[1]:p[2],regs);if(p.Length>3){var shift=Regex.Match(p[3],@"^lsl\s+#(\d+)$");right=right.HasValue&&shift.Success?right.Value<<int.Parse(shift.Groups[1].Value):(long?)null;}if(left.HasValue&&right.HasValue)v=i.Op.StartsWith("add")?left.Value+right.Value:left.Value-right.Value;}
   else if(new[]{"lsl","lsls","lsr","lsrs"}.Contains(i.Op)&&p.Length==3){long? left=Operand(p[1],regs),shift=Operand(p[2],regs);if(left.HasValue&&shift.HasValue&&shift>=0&&shift<=31)v=i.Op.StartsWith("lsl")?left.Value<<(int)shift.Value:(left.Value&0xffffffffL)>>(int)shift.Value;}
   else return false;
   if(v.HasValue)regs[dest]=v.Value&0xffffffffL;else regs.Remove(dest);return true;
  }
  static long? Target(byte[] bytes,int offset,uint stack,out int stubEnd){stubEnd=offset;var regs=new Dictionary<int,long>();var list=Decode(bytes,offset,64).Take(16).ToArray();if(list.Length==0||list[0].Op!="cpsid")return null;foreach(var ins in list.Skip(1)){if(ins.Op=="nop")continue;if(Load(ins,bytes,regs))continue;if(ins.Op=="bx"&&regs.ContainsKey(13)&&regs[13]==stack){stubEnd=ins.Address+ins.Size;long? target=Operand(ins.Args,regs);return target.HasValue&&(target.Value&1)==1?target:null;}return null;}return null;}
  static bool Stage(byte[] b,int offset){var regs=new Dictionary<int,long>();var writes=new HashSet<string>();foreach(var i in Decode(b,offset,1024)){if(i.Op=="cpsie")return writes.Count==3;if(i.Op=="str"){var m=Regex.Match(i.Args,@"\[([^\]]+)\]");if(m.Success){var p=m.Groups[1].Value.Split(',').Select(s=>s.Trim()).ToArray();long? a=Operand(p[0],regs);long? off=p.Length<2?0:Operand(p[1],regs);if(off.HasValue&&p.Length>=3){var shift=Regex.Match(p[2],@"^lsl\s+#(\d+)$");if(!shift.Success)off=null;else off<<=int.Parse(shift.Groups[1].Value);}if(a.HasValue&&off.HasValue){long addr=a.Value+off.Value;if(addr>=0xe000e180&&addr<0xe000e300)writes.Add("nvic");if(addr==0xe000e010)writes.Add("systick");if(addr==0xe000ed04)writes.Add("scb");}}}
    if(!Load(i,b,regs)&&!new[]{"str","strb","strh","cmp","cmn","tst","b","bne","beq","bcc","bcs","bhi","bls","bge","blt","ble","bgt","dsb","isb","nop"}.Contains(i.Op)){int dest=Reg(i.Args.Split(',')[0]);if(dest>=0)regs.Remove(dest);}
   }return false;}
  public static Obj Inspect(string path){var fi=new FileInfo(path);if(fi.Length<64||fi.Length>16*1024*1024)throw new Exception("Invalid firmware size");byte[] bytes=File.ReadAllBytes(path);var dicts=new List<Obj>();for(int i=0;i<bytes.Length-2;i++){if(bytes[i]!=0x78||((bytes[i]<<8)+bytes[i+1])%31!=0)continue;try{var obj=Json.Read(Encoding.UTF8.GetString(U.Inflate(bytes,i)));if(Json.S(obj,"app")=="Klipper")dicts.Add(obj);}catch{} }if(dicts.Count!=1)throw new Exception("Klipper MCU 정보를 하나로 확인할 수 없습니다.");var dict=dicts[0];string mcu=Json.S(Json.D(dict,"config"),"MCU").Trim().ToLowerInvariant();uint flash,ramStart,ramEnd;if(mcu=="rp2040"||mcu=="rp2350"){flash=0x10000000;ramStart=0x20000000;ramEnd=0x20082000;}else if(mcu.StartsWith("stm32")){flash=0x08000000;ramStart=0x20000000;ramEnd=0x30000000;}else if(mcu=="lpc1768"||mcu=="lpc1769"){flash=0;ramStart=0x10000000;ramEnd=0x10008000;}else throw new Exception("지원하지 않는 MCU: "+mcu);
   var candidates=new Dictionary<string,Obj>();foreach(int vector in mcu=="rp2040"?new[]{0,256}:new[]{0}){if(vector+64>bytes.Length)continue;uint stack=U.V32(bytes,vector),entry=U.V32(bytes,vector+4),reset=entry&~1u;if(stack%4!=0||stack<=ramStart||stack>ramEnd||(entry&1)==0||reset<flash||reset>=(long)flash+16*1024*1024)continue;int count=0;
    for(int offset=vector+64;offset<bytes.Length-2;offset+=2){if(bytes[offset]!=0x72||bytes[offset+1]!=0xb6)continue;if(++count>4096)throw new Exception("Ambiguous startup candidates");long start=(long)reset-offset;if(start<flash||start-flash>=16*1024*1024||(start-flash)%256!=0)continue;long? target=Target(bytes,offset,stack,out int stubEnd);if(!target.HasValue)continue;long stage=(target.Value&~1L)-start;if(stage<vector+64||stage>=bytes.Length-2||stage>=offset&&stage<stubEnd)continue;if(!Stage(bytes,(int)stage))continue;bool valid=true;foreach(int v in new[]{2,3,4,5,6,11,12,14,15}){uint ptr=U.V32(bytes,vector+v*4);if(ptr!=0&&((ptr&1)==0||!((ptr&~1u)>=start&&(ptr&~1u)<start+bytes.Length||(ptr&~1u)>=ramStart&&(ptr&~1u)<ramEnd))){valid=false;break;}}if(valid){var result=new Obj{{"mcu",mcu},{"version",Json.S(dict,"version")},{"flash_base",flash},{"application_start",start},{"bootloader_offset",start-flash},{"reset_handler",reset},{"reset_file_offset",offset},{"vector_file_offset",vector},{"size",bytes.Length},{"sha256",U.Hash(bytes)}};candidates[start+":"+offset+":"+vector]=result;}}
   }if(candidates.Count!=1)throw new Exception("BIN 시작 주소를 확정할 수 없어 업로드를 차단합니다.");return candidates.Values.Single();
  }
  public static void Compatible(Obj firmware,Obj board){if(Json.S(firmware,"mcu")!=Json.S(board,"mcu").Trim().ToLowerInvariant())throw new Exception("MCU 불일치: BIN="+Json.S(firmware,"mcu")+", board="+Json.S(board,"mcu"));if(Convert.ToInt64(firmware["application_start"])!=Convert.ToInt64(board["application_start"]))throw new Exception("펌웨어 시작 주소/부트로더 오프셋 불일치");}
 }
}
